def card(p):
    """Format a vocabulary profile as a plain-text terminal card (one line per item)."""
    lines = []

    if "word_count" in p:
        lines.append(f"Words: {p['word_count']}")

    if "unique_words" in p:
        lines.append(f"Unique: {p['unique_words']}")

    if "top_words" in p:
        top_str = ", ".join(f"{word} ({count})" for word, count in p["top_words"])
        lines.append(f"Top: {top_str}")

    return "\n".join(lines)
